    ctx.globalCompositeOperation='lighter';
    const sweep=surge>=0?(cy+0.9*S)-surge*1.9*S:-1e9;
    ctx.lineWidth=1;ctx.strokeStyle='rgba(70,215,255,'+(0.42*aWire*Math.min(1.6,glow))+')';ctx.beginPath();
